pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, LogFile} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint96 amount) public {
        vm.assume(actor != address(0));
        uint256 amt = bound(uint256(amount), 0, type(uint96).max);
        LogFile lg = new LogFile();
        vm.prank(actor);
        c.SetLogFile(address(lg));
        vm.deal(actor, amt);
        bool ok;
        if (amt > 0) {
            vm.prank(actor);
            try c.Deposit{value: amt}() { ok = true; } catch { ok = false; }
        } else {
            vm.prank(actor);
            try c.Deposit() { ok = true; } catch { ok = false; }
        }
        assertTrue(ok, "Deposit must succeed with a valid LogFile");
    }
}

