pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newLog) public {
        // freeze configuration: after Initialized(), SetLogFile must never succeed
        c.Initialized();
        bool ok;
        try c.SetLogFile(newLog) { ok = true; } catch { ok = false; }
        // General rule: after initialization, SetLogFile always reverts (Log stays unchanged).
        assertTrue(ok == false);
    }
}

