contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 2, 1 ether);

        uint256 before = c.balances(actor);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        uint256 afterBal = c.balances(actor);
        assertTrue(afterBal == before + amount, "balance must increase by the deposited amount");
